# Keep 5s where row + col is EVEN
def keep_even_sum(grid):
    result = [[0 for _ in range(len(grid[0]))] for _ in range(len(grid))]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                if (r + c) % 2 == 0:
                    result[r][c] = 5
            else:
                result[r][c] = grid[r][c]
    return result

